"""The rules of tic-tac-toe.

A board is a list of 9 cells, row by row, each "X", "O" or "" (empty).
X always moves first, so whose turn it is follows from the board itself.
"""

from dataclasses import dataclass

EMPTY = ""
SIZE = 9
MARKS = ("X", "O")
LINES = (
    (0, 1, 2),
    (3, 4, 5),
    (6, 7, 8),
    (0, 3, 6),
    (1, 4, 7),
    (2, 5, 8),
    (0, 4, 8),
    (2, 4, 6),
)


class IllegalMoveError(ValueError):
    """A move or a board that the rules do not allow."""


@dataclass(frozen=True)
class Outcome:
    """Where a game stands: "playing", "won" or "draw"."""

    status: str
    winner: str | None = None
    line: tuple[int, int, int] | None = None


def new_board() -> list[str]:
    return [EMPTY] * SIZE


def winning_line(board: list[str]) -> tuple[str, tuple[int, int, int]] | None:
    for line in LINES:
        a, b, c = (board[i] for i in line)
        if a and a == b == c:
            return a, line
    return None


def outcome(board: list[str]) -> Outcome:
    if found := winning_line(board):
        return Outcome("won", found[0], found[1])
    if all(board):
        return Outcome("draw")
    return Outcome("playing")


def turn(board: list[str]) -> str:
    """The mark that moves next."""
    return "X" if board.count("X") == board.count("O") else "O"


def legal_moves(board: list[str]) -> list[int]:
    if outcome(board).status != "playing":
        return []
    return [i for i, cell in enumerate(board) if not cell]


def validate(board: object) -> list[str]:
    """Check a board that came from outside and return it as a clean list."""
    if not isinstance(board, list) or len(board) != SIZE:
        raise IllegalMoveError("board must be a list of 9 cells")
    if any(cell not in (*MARKS, EMPTY) for cell in board):
        raise IllegalMoveError('cells must be "X", "O" or ""')
    x, o = board.count("X"), board.count("O")
    if x - o not in (0, 1):
        raise IllegalMoveError("X moves first and the players alternate")
    return list(board)


def play(board: list[str], cell: object) -> list[str]:
    """The board after the player to move takes `cell`. Does not change `board`."""
    # bool is a subclass of int, but true is not a square
    if not isinstance(cell, int) or isinstance(cell, bool) or not 0 <= cell < SIZE:
        raise IllegalMoveError("cell must be a whole number from 0 to 8")
    if outcome(board).status != "playing":
        raise IllegalMoveError("the game is over")
    if board[cell]:
        raise IllegalMoveError("that square is taken")
    after = list(board)
    after[cell] = turn(board)
    return after
"""The computer player.

Hard plays perfectly (negamax over the whole game tree, which is small
enough to search every move), so it never loses. Easy wins when it sees a
winning move and otherwise plays at random, which a casual player can beat.
"""

import random
from functools import cache

from . import game

LEVELS = ("easy", "hard")
WIN = 10


def choose_move(board: list[str], level: str, rng: random.Random | None = None) -> int:
    """The cell the computer plays for whoever's turn it is on `board`."""
    if level not in LEVELS:
        raise game.IllegalMoveError(f"level must be one of: {', '.join(LEVELS)}")
    moves = game.legal_moves(board)
    if not moves:
        raise game.IllegalMoveError("the game is over")
    if level == "hard":
        return best_move(tuple(board))
    me = game.turn(board)
    for cell in moves:
        if game.outcome(game.play(board, cell)).winner == me:
            return cell
    return (rng or random).choice(moves)


@cache
def best_move(board: tuple[str, ...]) -> int:
    """The best cell for the player to move; the lowest cell among equals."""
    moves = game.legal_moves(list(board))
    return max(moves, key=lambda cell: (-value(tuple(game.play(list(board), cell))), -cell))


@cache
def value(board: tuple[str, ...]) -> int:
    """How good `board` is for the player to move: positive wins, 0 draws.

    A win is worth more the sooner it comes, so Hard wins quickly and loses
    (never, in practice) as late as possible.
    """
    result = game.outcome(list(board))
    if result.status == "won":
        return -(WIN - (9 - board.count(game.EMPTY)))
    if result.status == "draw":
        return 0
    return max(-value(tuple(game.play(list(board), c))) for c in game.legal_moves(list(board)))
"""HTTP server: the page, its assets, and the JSON move API.

The server keeps no state between requests. The browser sends the whole
board with every move, the server checks it, plays the move (and the
computer's reply) and sends back the new board and where the game stands.
"""

import json
from http import HTTPStatus
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from pathlib import Path

from . import ai, game

STATIC = Path(__file__).parent / "static"
# Only these files are served: a fixed map, so no path from a request ever
# reaches the file system.
ASSETS = {
    "/": ("index.html", "text/html; charset=utf-8"),
    "/static/style.css": ("style.css", "text/css; charset=utf-8"),
    "/static/app.js": ("app.js", "text/javascript; charset=utf-8"),
}
MODES = ("computer", "friend")
MAX_BODY = 1024


def handle_move(request: object) -> dict:
    """Answer one POST /api/move body. Raises IllegalMoveError on bad input."""
    if not isinstance(request, dict):
        raise game.IllegalMoveError("the body must be a JSON object")
    board = game.validate(request.get("board"))
    mode = request.get("mode", "computer")
    if mode not in MODES:
        raise game.IllegalMoveError(f"mode must be one of: {', '.join(MODES)}")
    level = request.get("level", "hard")
    if mode == "computer":
        if level not in ai.LEVELS:
            raise game.IllegalMoveError(f"level must be one of: {', '.join(ai.LEVELS)}")
        if game.turn(board) != "X":
            raise game.IllegalMoveError("against the computer you play X")
    board = game.play(board, request.get("cell"))
    computer_move = None
    if mode == "computer" and game.outcome(board).status == "playing":
        computer_move = ai.choose_move(board, level)
        board = game.play(board, computer_move)
    return describe(board) | {"computer_move": computer_move}


def describe(board: list[str]) -> dict:
    result = game.outcome(board)
    return {
        "board": board,
        "status": result.status,
        "winner": result.winner,
        "line": list(result.line) if result.line else None,
        "turn": game.turn(board) if result.status == "playing" else None,
    }


class Handler(BaseHTTPRequestHandler):
    server_version = "tictactoe"

    def do_GET(self) -> None:
        self.serve(head=False)

    def do_HEAD(self) -> None:
        self.serve(head=True)

    def do_POST(self) -> None:
        if self.path != "/api/move":
            self.reply_json(HTTPStatus.NOT_FOUND, {"error": "not found"})
            return
        length = self.headers.get("Content-Length", "")
        if not length.isdigit():
            self.reply_json(HTTPStatus.LENGTH_REQUIRED, {"error": "Content-Length required"})
            return
        if int(length) > MAX_BODY:
            self.reply_json(HTTPStatus.REQUEST_ENTITY_TOO_LARGE, {"error": "body too large"})
            return
        try:
            request = json.loads(self.rfile.read(int(length)) or b"null")
            self.reply_json(HTTPStatus.OK, handle_move(request))
        except (ValueError, game.IllegalMoveError) as error:
            # json.JSONDecodeError and IllegalMoveError are both ValueErrors
            self.reply_json(HTTPStatus.BAD_REQUEST, {"error": str(error)})

    def serve(self, *, head: bool) -> None:
        path = self.path.split("?", 1)[0]
        if path == "/health":
            self.reply(HTTPStatus.OK, b"ok", "text/plain; charset=utf-8", head=head)
        elif path in ASSETS:
            name, content_type = ASSETS[path]
            self.reply(HTTPStatus.OK, (STATIC / name).read_bytes(), content_type, head=head)
        elif path == "/api/move":
            self.send_response(HTTPStatus.METHOD_NOT_ALLOWED)
            self.send_header("Allow", "POST")
            self.send_header("Content-Length", "0")
            self.end_headers()
        else:
            self.reply(HTTPStatus.NOT_FOUND, b"not found", "text/plain; charset=utf-8", head=head)

    def reply_json(self, status: HTTPStatus, body: dict) -> None:
        self.reply(status, json.dumps(body).encode(), "application/json")

    def reply(
        self, status: HTTPStatus, body: bytes, content_type: str, *, head: bool = False
    ) -> None:
        self.send_response(status)
        self.send_header("Content-Type", content_type)
        self.send_header("Content-Length", str(len(body)))
        self.send_header("Cache-Control", "no-cache")
        self.send_header("X-Content-Type-Options", "nosniff")
        self.end_headers()
        if not head:
            self.wfile.write(body)


def make_server(host: str, port: int) -> ThreadingHTTPServer:
    return ThreadingHTTPServer((host, port), Handler)

